INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-dfa8fbfe', 'https://www.theguardian.com/global-development/2026/sep/11/15m-fund-launched-to-create-unstoppable-momentum-to-end-fgm-worldwide', '$15m fund launched to create ''unstoppable momentum'' to end FGM worldwide', 'Frontline activists and human rights leaders have welcomed the launch of the $15.5m Her Horizon Fund, established by the Wallace Global Fund to support survivor-led community initiatives aimed at eliminating female genital mutilation (FGM) globally. The philanthropic effort comes amid declining global donor funding for bodily integrity initiatives and mounting political challenges to statutory protections against non-consensual genital cutting.', 'The Guardian', 'Provides essential documentation on global philanthropic investment and activist mobilization surrounding female bodily autonomy and institutional efforts to end non-consensual female genital modification.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-02d10567', 'https://www.ynetnews.com/article/syj73x3200', 'More than a bandage: Europe''s circumcision crackdown spurs Jewish push to safeguard brit milah', 'In response to intensifying legal scrutiny, police investigations, and legislative proposals in European nations restricting non-therapeutic infant male circumcision, Jewish leadership organizations established the Brussels-based Center of Excellence for Religious Male Circumcision (CERM). The article outlines ongoing tensions between state regulations, child health oversight, anti-circumcision campaigns, and religious freedom guarantees.', 'Ynet News', 'Captures critical legal, social, and policy shifts in Europe concerning infant male circumcision and legal challenges framed around child rights and bodily integrity.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-a1c1a821', 'https://www.enca.com/news/police-probe-after-grade-5-pupil-circumcised-school', 'Police probe after Grade 5 pupil circumcised at school', 'Law enforcement and education officials in Gauteng, South Africa, launched a criminal investigation after an 11-year-old primary school student was allegedly forcibly subjected to an unauthorized circumcision by peers in a school facility. The incident has drawn widespread scrutiny from child protection authorities and community members regarding consent, physical security, and forced genital interventions.', 'eNCA', 'Documents a significant real-world criminal case involving non-consensual, unauthorized circumcision of a minor, directly relevant to archival records on consent, bodily integrity, and child protection.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-c0b3037d', 'https://www.contagionlive.com/view/new-study-links-rates-of-male-circumcision-to-hiv-2-prevalence', 'New Study Links Rates of Male Circumcision to HIV-2 Prevalence', 'A public health study examining historical male circumcision rates across 218 ethnic groups in West Africa revealed a strong inverse correlation with HIV-2 seroprevalence. The findings expand epidemiological arguments previously focused on HIV-1 to HIV-2, highlighting how public health frameworks continue to analyze male circumcision as a disease prevention strategy.', 'Contagion Live', 'Provides important contemporary epidemiological literature on male circumcision, essential for archiving how medical and public health institutions evaluate foreskin removal.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-6f7f7189', 'https://www.futurity.org/circumcision-autism-risk-3342752/', 'Male circumcision just after birth doesn''t raise autism risk', 'A national study led by researchers at the Johns Hopkins Bloomberg School of Public Health and published in JAMA Pediatrics evaluated medical data from nearly 3,000 boys to investigate claims linking neonatal male circumcision to autism spectrum disorder. The study found no statistically significant correlation between early infant circumcision and autism, clarifying long-standing debates regarding potential neurodevelopmental impacts.', 'Futurity', 'Contributes key peer-reviewed epidemiological research addressing long-debated hypotheses regarding potential neurological and developmental outcomes of neonatal circumcision.', 'pending');
